                        if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color
                                and (nx,ny) not in seen):
                            seen.add((nx,ny))
                            stack.append((nx,ny))
                result.append(cells)
        return result

    def box(obj):
        return (min(r for r,c in obj), max(r for r,c in obj),
                min(c for r,c in obj), max(c for r,c in obj))

    objects = []
    for color in colors - {bg}:
        objects.extend(components(color))

    rectangles = {}
    frames = []
    for obj in objects:
        a,b,c,d = box(obj)
        if len(obj) == (b-a+1)*(d-c+1):
            rectangles[(b-a+1,d-c+1)] = grid[obj[0][0]][obj[0][1]]
        else:
            frames.append(obj)

    best = None
    for obj in frames:
        a,b,c,d = box(obj)
        crop = [row[c:d+1] for row in grid[a:b+1]]
        hh, ww = b-a+1, d-c+1
        unseen = {(r,col) for r in range(hh) for col in range(ww)
                  if crop[r][col] == bg}
        holes = []
        while unseen:
            start = next(iter(unseen))
            unseen.remove(start)
            stack, cells = [start], []
            while stack:
                r,col = stack.pop()
                cells.append((r,col))
                for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
                    p = (r+dr,col+dc)
                    if p in unseen:
                        unseen.remove(p)
                        stack.append(p)
            holes.append(cells)
        matches = []
        for cells in holes:
            rs = [r for r,c in cells]; cs = [c for r,c in cells]
            dims = (max(rs)-min(rs)+1, max(cs)-min(cs)+1)
            matches.append(rectangles.get(dims))
        score = sum(color is not None for color in matches)
        if best is None or score > best[0]:
            best = (score, crop, holes, matches)

    _, result, holes, matches = best
    for cells, color in zip(holes, matches):
        if color is None:
